import sys
from collections import deque

data = sys.stdin.read().split()
n = int(data[0]); k = int(data[1])
a = list(map(int, data[2:2 + n]))
start = tuple(1 if x <= k else 0 for x in a)

def grouped(p):
    idx = [i for i in range(n) if p[i]]
    return not idx or idx[-1] - idx[0] + 1 == len(idx)

dist = {start: 0}
q = deque([start])
ans = None
while q:
    p = q.popleft()
    if grouped(p):
        ans = dist[p]
        break
    for i in range(n):
        for j in range(i + 1, n):
            if p[i] != p[j]:
                l = list(p)
                l[i], l[j] = l[j], l[i]
                t = tuple(l)
                if t not in dist:
                    dist[t] = dist[p] + 1
                    q.append(t)
print(ans)

